// Bundles the runtime MyGo injects into every page into
// internal/bridge/bridge.js, which the Go package embeds. The output is
// committed, so Go users never need Bun.
import { join } from "node:path";

const out = join(import.meta.dir, "../../internal/bridge/bridge.js");
const result = await Bun.build({
  entrypoints: [join(import.meta.dir, "src/bridge.ts")],
  format: "iife",
  target: "browser",
  minify: true,
});
if (!result.success) {
  for (const log of result.logs) console.error(log);
  process.exit(1);
}
const code = (await result.outputs[0]!.text()).trim();
await Bun.write(out, "// Code generated by `bun run build` from packages/bridge. DO NOT EDIT.\n" + code + "\n");
console.log(`wrote ${out} (${code.length} bytes)`);
